mapper.select:
SELECT s.id, s.name, s.no, s.gender, s.phone, s.id_card, s.degree, s.is_college, s.address, s.graduation_date, s.violation_count, s.violation_score, s.clazz_id, c.name AS clazz_name, s.create_time, s.update_time FROM student s LEFT JOIN clazz c ON s.clazz_id = c.id
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.degree = #{degree}
AND s.clazz_id = #{clazzId}
ORDER BY s.id

mapper.update:
UPDATE student
name = #{name}, no = #{no}, gender = #{gender}, phone = #{phone}, id_card = #{idCard}, degree = #{degree}, is_college = #{isCollege}, address = #{address}, graduation_date = #{graduationDate}, clazz_id = #{clazzId},
WHERE id = #{id}

UPDATE student
SET violation_count = violation_count + 1,
    violation_score = violation_score + #{score}
WHERE id = #{id}
